from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone("America/New_York")
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None

        self.expiration_block_date = None
        self.exercise_handled_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy_symbol, consolidator)

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        self.HandleUnexpectedEquityPosition(today)
        self.HandleExpirationProcessing(today)

        if self.held_option is not None and self.entry_price is not None:
            self.EvaluateProfitTarget(slice)
            self.EvaluateTimeStop(today)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        end_time = bar.EndTime
        end_date = end_time.date()
        end_clock = end_time.time()

        # Only use regular-session bars. Consolidator boundaries are aligned
        # to New York clock time, so the first bar ends at 09:35.
        if end_clock < time(9, 35) or end_clock > time(16, 0):
            return

        self.fast_values.append(bar.Close)
        self.slow_values.append(bar.Close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = sum(list(self.fast_values)[-5:]) / 5.0
        current_slow = sum(self.slow_values) / 20.0

        bullish_cross = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= end_clock <= time(14, 30)):
            return

        self.TryEnterCall(end_date, bar.Close)

    def TryEnterCall(self, algorithm_date, spy_price):
        if self.current_slice is None:
            return

        if self.expiration_block_date == algorithm_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            return

        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price")
            return

        chains = list(self.current_slice.OptionChains)
        if not chains:
            self.Debug("Skipped selection: no option chain")
            return

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < algorithm_date + timedelta(days=7):
                    continue
                contracts.append(contract)

        if not contracts:
            self.Debug("Skipped selection: no qualifying expiration")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Call entry submitted: {selected.Symbol} "
            f"expiry={nearest_expiry} strike={selected.Strike}"
        )

    def EvaluateProfitTarget(self, slice: Slice):
        symbol = self.held_option
        if symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self.entry_price:
            return

        self.SubmitExit("profit target")

    def EvaluateTimeStop(self, algorithm_date):
        symbol = self.held_option
        expiry_date = self.Securities[symbol].Symbol.ID.Date.date()

        previous_trading_day = expiry_date - timedelta(days=1)
        while not self.Securities[symbol].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        if (
            algorithm_date == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("expiration time stop")

    def HandleExpirationProcessing(self, algorithm_date):
        if self.held_option is None:
            return

        expiry_date = self.Securities[
            self.held_option
        ].Symbol.ID.Date.date()

        if algorithm_date >= expiry_date:
            self.expiration_block_date = algorithm_date
            self.SubmitExit("expiration safeguard")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ):
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Call exit submitted: {reason}")

    def HandleUnexpectedEquityPosition(self, algorithm_date):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            return

        if self.exercise_handled_date != algorithm_date:
            self.exercise_handled_date = algorithm_date
            self.expiration_block_date = algorithm_date
            self.Debug(
                f"Unexpected SPY equity position detected: {quantity}; "
                "liquidating immediately"
            )

        self.MarketOrder(
            self.spy_symbol,
            -quantity,
            tag="unexpected exercise or assignment"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"Call entry filled: {self.held_option} "
                        f"price={self.entry_price}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Call exit filled: {order_event.Symbol} "
                        f"price={order_event.FillPrice}"
                    )
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None
                    self.entry_ticket = None
                elif order_event.Status in (
