            return

        algorithm_date = self.Time.date()
        eligible_expirations = []

        for chain in chains:
            for contract in chain:
                expiration_date = contract.Expiry.date()
                days = (expiration_date - algorithm_date).days
                if contract.Right == OptionRight.Call and days >= 7:
